import csv, json
from datetime import date
from decimal import Decimal, ROUND_HALF_UP

AUDIT = date(2026, 9, 1)

def parse_bool(s):
    return str(s).strip().lower() == 'true'

def round2(x):
    return Decimal(x).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def cap_str(cap):
    return str(cap.quantize(Decimal('0.01')))

# Dedupe table_health: last row per table_name wins.
rows = list(csv.DictReader(open('input/table_health.csv')))
last = {}
for i, r in enumerate(rows):
    last[r['table_name']] = (i, r)

aliases = {r['alias']: r['table_name'] for r in csv.DictReader(open('input/table_aliases.csv'))}

# Reindex log: last row per table_name wins.
reindex = {}
for i, r in enumerate(csv.DictReader(open('input/reindex_log.csv'))):
    reindex[r['table_name']] = (i, r)

# Change-control tickets: last row resolving to a table wins.
tickets = {}
for i, r in enumerate(csv.DictReader(open('input/change_control_tickets.csv'))):
    target = aliases.get(r['table_ref'], r['table_ref'])
    r['_target'] = target
    tickets[target] = (i, r)

records = []
for name, (i, r) in sorted(last.items(), key=lambda kv: (kv[1][1]['last_analyzed'], kv[0])):
    total = int(r['total_pages'])
    dead = int(r['dead_pages'])
    ratio = round2(Decimal(dead) / Decimal(total))
    size_class = 'large' if total >= 500 else 'small'
    base_cap = Decimal('0.2') if size_class == 'large' else Decimal('0.4')
    last_analyzed = date.fromisoformat(r['last_analyzed'])
    days = (AUDIT - last_analyzed).days
    stale = days >= 30
    effective_cap = base_cap - (Decimal('0.10') if size_class == 'large' else Decimal('0.05')) if stale else base_cap

    autovac_disabled = (not parse_bool(r['autovacuum_enabled'])) or (r['vacuum_type'] == 'manual')

    reind = reindex.get(name)
    reindex_exempt = False
    reindex_rec = reind[1] if reind else None
    if parse_bool(r['maintenance_active']) and reindex_rec:
        if parse_bool(reindex_rec['approved']) and date.fromisoformat(reindex_rec['valid_until']) > AUDIT:
            reindex_exempt = True

    bloat_exceeded = ratio > effective_cap

    ticket = tickets.get(name)
    ticket_rec = ticket[1] if ticket else None
    hold_qual = False
    if ticket_rec:
        hold_qual = (
            ticket_rec['exception_type'] == 'BLOAT_HOLD'
            and ticket_rec['status'] == 'Closed'
            and parse_bool(ticket_rec['approved'])
            and date.fromisoformat(ticket_rec['valid_until']) > AUDIT
        )

    if autovac_disabled:
        finding = 'AUTOVACUUM_DISABLED'
    elif bloat_exceeded and not reindex_exempt:
        if hold_qual:
            finding = 'STALE_STATISTICS' if stale else 'none'
        else:
            finding = 'BLOAT_THRESHOLD_EXCEEDED'
    elif stale:
        finding = 'STALE_STATISTICS'
    else:
        finding = 'none'

    records.append({
        'table_name': name,
        'size_class': size_class,
        'bloat_ratio': str(ratio),
        'finding': finding,
        # debug/evidence fields:
        'total_pages': total,
        'dead_pages': dead,
        'ratio': str(ratio),
        'base_cap': cap_str(base_cap),
        'effective_cap': cap_str(effective_cap),
        'days': days,
        'stale': stale,
        'legacy_size_class': r['size_class'],
        'legacy_days_since_analyze': r['days_since_analyze'],
        'autovacuum_enabled': r['autovacuum_enabled'],
        'vacuum_type': r['vacuum_type'],
        'maintenance_active': r['maintenance_active'],
        'reindex_exempt': reindex_exempt,
        'reindex_rec': reindex_rec,
        'bloat_exceeded': bloat_exceeded,
        'ticket_rec': ticket_rec,
        'hold_qual': hold_qual,
        'last_analyzed': r['last_analyzed'],
    })

# Write bloat_audit.csv
with open('bloat_audit.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['table_name', 'size_class', 'bloat_ratio', 'finding'])
    for r in records:
        w.writerow([r['table_name'], r['size_class'], r['bloat_ratio'], r['finding']])

# Write results.json
counts = {
    'flagged_count': sum(1 for r in records if r['finding'] != 'none'),
    'autovacuum_disabled_count': sum(1 for r in records if r['finding'] == 'AUTOVACUUM_DISABLED'),
    'bloat_exceeded_count': sum(1 for r in records if r['finding'] == 'BLOAT_THRESHOLD_EXCEEDED'),
    'stale_statistics_count': sum(1 for r in records if r['finding'] == 'STALE_STATISTICS'),
    'compliant_count': sum(1 for r in records if r['finding'] == 'none'),
}
with open('results.json', 'w') as f:
    json.dump(counts, f, indent=2)
    f.write('\n')

def legacy_size_note(r):
    if r['legacy_size_class'] == 'medium':
        return 'legacy medium trap ignored'
    if r['legacy_size_class'] != r['size_class']:
        return f"legacy {r['legacy_size_class']} ignored"
    return f"legacy {r['legacy_size_class']} matched"

def ticket_note(r):
    t = r['ticket_rec']
    if not t:
        return ''
    tid = t['ticket_id']
    if r['hold_qual']:
        if r['finding'] == 'AUTOVACUUM_DISABLED':
            return f"{tid} BLOAT_HOLD ticket exists, but a hold never clears autovacuum."
        if r['finding'] == 'STALE_STATISTICS':
            return f"{tid} BLOAT_HOLD ticket is a qualifying hold, so bloat is suppressed but stale stats remain."
        return f"{tid} BLOAT_HOLD ticket is a qualifying hold, so bloat is suppressed."
    if t['exception_type'] != 'BLOAT_HOLD':
        return f"{tid} {t['exception_type']} ticket does not qualify as a bloat hold."
    if t['status'] != 'Closed':
        return f"{tid} BLOAT_HOLD ticket is rejected because status {t['status']} is not Closed."
    if not parse_bool(t['approved']):
        return f"{tid} BLOAT_HOLD ticket is rejected because approved is {t['approved']}."
    if not date.fromisoformat(t['valid_until']) > AUDIT:
        return f"{tid} BLOAT_HOLD ticket is rejected because valid_until {t['valid_until']} is not after 2026-09-01."
    return f"{tid} BLOAT_HOLD ticket was checked but does not change this finding."

def reindex_note(r):
    if not (r['maintenance_active'] == 'True' or r['reindex_rec']):
        return ''
    if r['reindex_exempt']:
        return f"reindex valid_until {r['reindex_rec']['valid_until']} is valid after 2026-09-01, so bloat is exempt."
    if r['reindex_rec'] and not parse_bool(r['reindex_rec']['approved']):
        return f"unapproved reindex approved={r['reindex_rec']['approved']} does not exempt bloat."
    if r['reindex_rec'] and not date.fromisoformat(r['reindex_rec']['valid_until']) > AUDIT:
        return f"reindex valid_until {r['reindex_rec']['valid_until']} is no longer valid because it is not after 2026-09-01."
    return "maintenance_active=True has no valid reindex exemption."

memo_lines = []
memo_lines.append('# Monthly Table Maintenance Review Memo')
memo_lines.append('')
memo_lines.append('Audit date: 2026-09-01. Size class is computed from total_pages only (>=500 large, <500 small), ignoring the legacy size_class column including medium traps. Bloat ratio is computed as dead_pages / total_pages with round-half-up to 2 decimal places. A ratio exactly equal to the applicable cap is compliant because the policy flags only ratios strictly over the cap; when stats are stale, the effective tightened cap governs the comparison.')
memo_lines.append('')
memo_lines.append('## Non-compliant findings')
memo_lines.append('')

for r in records:
    if r['finding'] == 'none':
        continue
    parts = []
    parts.append(f"{r['table_name']} is {r['finding']}")
    parts.append(f"computed size_class {r['size_class']} from total_pages {r['total_pages']}")
    if r['legacy_size_class'] != r['size_class'] or r['legacy_size_class'] == 'medium':
        parts.append(legacy_size_note(r))
    parts.append(f"dead_pages {r['dead_pages']} and total_pages {r['total_pages']} give computed round-half-up ratio {r['ratio']}")
    if r['stale']:
        parts.append(f"stats are stale at {r['days']} days, which tightened cap to {r['effective_cap']}; legacy days_since_analyze field ignored")
    else:
        parts.append(f"cap is {r['effective_cap']}")
    if r['finding'] == 'AUTOVACUUM_DISABLED':
        if r['vacuum_type'] == 'manual':
            parts.append(f"manual vacuum override disables autovacuum even though autovacuum_enabled is {r['autovacuum_enabled']}")
        else:
            parts.append(f"autovacuum_enabled is {r['autovacuum_enabled']}, so autovacuum is disabled")
    elif r['finding'] == 'BLOAT_THRESHOLD_EXCEEDED':
        if r['bloat_exceeded']:
            parts.append(f"ratio exceeds the cap")
    elif r['finding'] == 'STALE_STATISTICS':
        if r['bloat_exceeded']:
            parts.append("bloat was checked before staleness")
        else:
            parts.append("ratio does not exceed the cap")
    rn = reindex_note(r)
    if rn:
        parts.append(rn)
    tn = ticket_note(r)
    if tn:
        parts.append(tn)
    # Join into one prose sentence/bullet.
    bullet = '- ' + ', '.join(parts) + '.'
    memo_lines.append(bullet)

with open('bloat_memo.md', 'w') as f:
    f.write('\n'.join(memo_lines) + '\n')

print('Wrote bloat_audit.csv, bloat_memo.md, results.json')
print(json.dumps(counts, indent=2))
